JS = '''
const key='athar-template:'+location.pathname;const sheets=document.querySelector('main');
try{const saved=localStorage.getItem(key);if(saved)sheets.innerHTML=saved}catch{}
sheets.addEventListener('input',()=>{try{localStorage.setItem(key,sheets.innerHTML);document.getElementById('status').textContent='Saved on this browser / تم الحفظ محلياً'}catch{document.getElementById('status').textContent='Use Download to save / استخدم التنزيل للحفظ'}});
function saveTemplate(){const clone=document.documentElement.cloneNode(true);clone.querySelectorAll('[contenteditable]').forEach(e=>e.setAttribute('contenteditable','true'));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['<!doctype html>'+clone.outerHTML],{type:'text/html;charset=utf-8'}));a.download=location.pathname.split('/').pop();a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function resetTemplate(){if(confirm('Reset edits to the original template? / إعادة الحقول إلى القالب الأصلي؟')){localStorage.removeItem(key);location.reload()}}
'''
def document(slug,en,arabic,pages,mode='a4'):
    number=int(slug[:2])
    body=''
    for n,p in enumerate(pages,1):
        classes='sheet'+(' cover' if p['cover'] else '')+(' card-sheet' if mode=='card' else ' slide-sheet' if mode=='slides' else '')
        body+=f'<section class="{classes}" data-page="{n}">'+(header() if mode!='card' else '')
        if mode!='card': body+=f'<div class="kicker">ATHAR / {number:02d} · {esc(p["ref"])}</div>'+pair(f'<h1>{esc(p["en"])}</h1>',f'<h1>{esc(p["ar"])}</h1>','title pair')
        body+=f'<div class="page-content">{p["body"]}</div><footer><div class="contact">{field("hello@athar.example · +966 5X XXX XXXX")}<br>{field("Riyadh, Saudi Arabia / الرياض، المملكة العربية السعودية")}</div><div>{esc(p["ref"])} · v1.0<br>2026-10-02 · {n:02d} / {len(pages):02d}</div></footer></section>'
    style=CSS+'''
    body{line-height:1.5}[lang=ar]{line-height:1.7}header{height:26mm;margin-bottom:6mm;padding-bottom:4mm}.title{margin-bottom:6mm}h2{margin-top:4mm}.grid{gap:3mm;margin:3mm 0}.data{padding:2.5mm 3mm}.note{margin:4mm 0;padding:2.5mm 3mm}.signature{height:14mm}.stamp-area{height:14mm;margin-top:4mm}
    .card-front img{width:29mm;height:29mm}.card-front [lang=ar]{font-size:7pt}.card-sheet .pair{gap:3mm}.card-sheet h1{font-size:10pt;line-height:1.3}.card-sheet .qr{width:21mm;height:21mm}.card-sheet p{line-height:1.6;font-size:7pt;margin:1mm 0}.card-sheet footer{font-size:4.5pt;bottom:2mm;padding-top:1mm}.card-sheet footer .contact{display:none}.card-sheet footer>div:last-child{margin-left:auto}.card-sheet .page-content{padding-top:1mm}.slide-sheet header{height:25mm}
    '''+('@page{size:85mm 55mm;margin:0}' if mode=='card' else '@page{size:338.667mm 190.5mm;margin:0}' if mode=='slides' else '')
    word_images = {f'../assets/{name}': 'data:image/png;base64,' + base64.b64encode((ASSETS/name).read_bytes()).decode() for name in ['Athar-Symbol.png', 'Athar-Horizontal.png', 'Athar-Int.png', 'contact-qr.png'] if f'src="../assets/{name}"' in body}
    runtime=JS+'\nwindow.atharWordImages='+json.dumps(word_images)+';\n'+(ASSETS/'word-export.js').read_text()
    extra=''
    encoder=''
    if mode=='card':
        runtime=runtime.replace("sheets.addEventListener('input',()=>{try{", "sheets.addEventListener('input',()=>{window.updateContactQr();try{")
        runtime=runtime.replace('function saveTemplate(){', 'function saveTemplate(){window.updateContactQr();')
        encoder='<script>'+ (ASSETS/'qrcode-generator.js').read_text()+'</script>'
        extra='<script>'+ (ASSETS/'business-card.js').read_text()+'</script>'
    output=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(en)} | أثر الذكاء</title><style>{style}</style></head><body><nav class="toolbar"><a href="../index.html">← Library / المكتبة</a><button onclick="window.print()">Print / PDF · طباعة</button><button onclick="exportWord(this)">Export Word / تصدير Word</button><button onclick="saveTemplate()">Download edits / تنزيل</button><button onclick="resetTemplate()">Reset / إعادة</button><span id="status" class="status">Click underlined fields to edit / انقر الحقول المسطرة للتعديل</span></nav><main>{body}</main>{encoder}<script>{runtime}</script>{extra}</body></html>'''
    (ROOT/'templates'/f'{slug}.html').write_text(output)
    DOCS.append(dict(slug=slug,en=en,ar=arabic,pages=len(pages),mode=mode))

def section(en, arabic, entext, artext): return heading(en,arabic)+text(entext,artext)
def table(rows):
    headers=[('Description','الوصف'),('Qty','الكمية'),('Unit SAR','سعر الوحدة'),('Discount SAR','الخصم'),('VAT %','الضريبة'),('Net SAR','الصافي')]
    out='<table><thead><tr>'+''.join(f'<th class="{("num" if i else "")}">{e}{ar(a)}</th>' for i,(e,a) in enumerate(headers))+'</tr></thead><tbody>'
    for row in rows:
        out+='<tr>'+''.join(f'<td class="{("num" if i else "")}">{field(v)}</td>' for i,v in enumerate(row))+'</tr>'
    return out+'</tbody></table>'
ROWS=[('AI discovery workshop / ورشة استكشاف الذكاء الاصطناعي','2','5,000.00','0.00','15','10,000.00'),('Solution architecture / تصميم بنية الحل','1','8,000.00','500.00','15','7,500.00')]
def totals():
    return '<div class="totals">'+''.join(f'<div class="{cls}"><span>{en} / {ar(a)}</span>{field(v)}</div>' for en,a,v,cls in [('Subtotal','المجموع الفرعي','18,000.00',''),('Discount','الخصم','500.00',''),('Taxable amount','المبلغ الخاضع','17,500.00',''),('VAT 15%','ضريبة ١٥٪','2,625.00',''),('Total SAR','الإجمالي ر.س','20,125.00','grand')])+'</div>'
def company_details():
    return grid(box('Legal company name','اسم الشركة القانوني','[Athar Intelligence / أثر الذكاء]'),box('CR / VAT number','السجل التجاري / الرقم الضريبي','[CR] / [15-digit VAT number]'),box('National address','العنوان الوطني','[Building, street, district, city, postal code, additional no.]'),box('Contact','التواصل','hello@athar.example · +966 5X XXX XXXX'))
def customer_details(label='Customer',arabic='العميل'):
    return heading(label,arabic)+grid(box('Legal name / Contact','الاسم القانوني / جهة الاتصال','[Customer legal name / اسم العميل]'),box('VAT number / CR','الرقم الضريبي / السجل','[VAT number] / [CR]'),box('National address','العنوان الوطني','[Building, street, district, city, postal code, additional no.]'),box('Email / Mobile','البريد الإلكتروني / الجوال','[client@example.com] · [Mobile]'))
def payment():
    return grid(box('Beneficiary / Bank','المستفيد / البنك','[Legal company name] / [Bank]'),box('IBAN / Payment reference','آيبان / مرجع الدفع','[SA + 22 digits] / [Document reference]'))

def build_documents():
    # 01 — Company profile, 11 pages
    ref='AI-PRF-2026-001'
    pages=[cover('Company profile','الملف التعريفي','Where intelligence creates impact.','حيث يصنع الذكاء أثراً.',ref)]
    pages.append(page('About Athar','عن أثر الذكاء',section('Intelligence, applied.','ذكاء يترجم إلى أثر','Athar Intelligence is a Saudi-focused AI and technology consultancy built to help organizations turn complex data into practical business decisions. This profile presents a proposed company positioning for founder approval.','أثر الذكاء شركة استشارات في الذكاء الاصطناعي والتقنية تستهدف السوق السعودي، وتساعد المنشآت على تحويل البيانات المعقدة إلى قرارات عملية. يعرض هذا الملف تصوراً تعريفياً مقترحاً لاعتماد المؤسسين.')+section('Our approach','منهجيتنا','We begin with the business challenge, assess readiness, design a focused solution, and support implementation with measurable outcomes.','نبدأ بتحديات الأعمال، ونقيّم الجاهزية، ونصمم حلولاً محددة، وندعم التنفيذ بمخرجات قابلة للقياس.')+grid(box('Established','سنة التأسيس','[2026]'),box('Headquarters','المقر الرئيسي','[Riyadh / الرياض]'),box('Legal entity','الكيان القانوني','[Registered legal name]'),box('Commercial registration','السجل التجاري','[CR number]')),ref))
    pages.append(page('Vision & mission','الرؤية والرسالة',section('Our vision','رؤيتنا','To be a trusted partner in building a future where intelligence creates lasting value for Saudi organizations.','أن نكون شريكاً موثوقاً في بناء مستقبل يصنع فيه الذكاء قيمة مستدامة للمنشآت السعودية.')+section('Our mission','رسالتنا','Make AI useful, understandable and accountable through sound strategy, thoughtful engineering and effective knowledge transfer.','جعل الذكاء الاصطناعي مفيداً ومفهوماً وقابلاً للمساءلة من خلال استراتيجية واضحة وهندسة مدروسة ونقل فعال للمعرفة.')+note('Proposed statements for founder approval.','عبارات مقترحة لاعتماد المؤسسين.'),ref))
    values=[('Integrity','النزاهة','Clear expectations and honest reporting.','توقعات واضحة وتقارير صادقة.'),('Impact','الأثر','Business value guides every decision.','قيمة الأعمال توجه كل قرار.'),('Excellence','التميز','Reliable engineering and careful delivery.','هندسة موثوقة وتنفيذ متقن.'),('Partnership','الشراكة','Work with people and transfer knowledge.','نعمل مع الأفراد وننقل المعرفة.')]
    pages.append(page('Our values','قيمنا',''.join(section(*v) for v in values),ref))
    services=[('AI strategy & readiness','استراتيجية الذكاء الاصطناعي والجاهزية','Readiness assessment, use-case prioritization and delivery roadmaps.','تقييم الجاهزية وترتيب حالات الاستخدام وإعداد خرائط التنفيذ.'),('Applied AI & automation','الذكاء الاصطناعي التطبيقي والأتمتة','Assistants, document intelligence and workflow automation.','المساعدات الذكية ومعالجة المستندات وأتمتة سير العمل.'),('Data & analytics','البيانات والتحليلات','Data foundations, decision dashboards and actionable insights.','أسس البيانات ولوحات القرار والرؤى القابلة للتطبيق.'),('Enablement & advisory','التمكين والاستشارات','Executive workshops, team training and operating-model support.','ورش القيادات وتدريب الفرق ودعم نماذج التشغيل.')]
    pages.append(page('Our services','خدماتنا',''.join(section(*s) for s in services),ref))
