def build_pptx(slides):
    from pptx import Presentation
    from pptx.util import Inches, Pt
    from pptx.dml.color import RGBColor
    from pptx.enum.text import PP_ALIGN
    from pptx.enum.chart import XL_CHART_TYPE, XL_LEGEND_POSITION
    from pptx.chart.data import CategoryChartData
    from pptx.oxml.xmlchemy import OxmlElement
    prs=Presentation();prs.slide_width=Inches(13.333);prs.slide_height=Inches(7.5)
    def color(h): return RGBColor.from_string(h.strip('#'))
    def tb(slide,x,y,w,h,txt,size=18,arabic=False,bold=False,ink=NAVY):
        shape=slide.shapes.add_textbox(Inches(x),Inches(y),Inches(w),Inches(h));tf=shape.text_frame;tf.word_wrap=True
        for i,line in enumerate(txt.split('\n')):
            p=tf.paragraphs[0] if i==0 else tf.add_paragraph();p.text=line;p.font.name='IBM Plex Sans Arabic' if arabic else 'Manrope';p.font.size=Pt(size);p.font.bold=bold;p.font.color.rgb=color(ink)
            if arabic:
                p.alignment=PP_ALIGN.RIGHT;p._p.get_or_add_pPr().set('rtl','1')
                for r in p.runs:
                    rpr=r._r.get_or_add_rPr();rpr.set('lang','ar-SA');cs=OxmlElement('a:cs');cs.set('typeface','IBM Plex Sans Arabic');rpr.append(cs)
        return shape
    def rect(s,x,y,w,h,fill):
        sh=s.shapes.add_shape(1,Inches(x),Inches(y),Inches(w),Inches(h));sh.fill.solid();sh.fill.fore_color.rgb=color(fill);sh.line.fill.background();return sh
    def bilingual(s,e,a,y=2.2):
        tb(s,.75,y,5.6,2.8,e,20);tb(s,6.9,y,5.6,2.8,a,22,True)
    for i,p in enumerate(slides):
        s=prs.slides.add_slide(prs.slide_layouts[6]);s.background.fill.solid();s.background.fill.fore_color.rgb=color('#FFFFFF')
        rect(s,0,0,13.333,.07,NAVY);s.shapes.add_picture(str(ASSETS/'Athar-Horizontal.png'),Inches(.75),Inches(.25),width=Inches(2.25))
        tb(s,8.0,.4,4.5,.5,'ATHAR INTELLIGENCE · أثر الذكاء',11,True)
        tb(s,.75,1.22,5.7,.8,p['en'],28,bold=True);tb(s,6.85,1.22,5.7,.8,p['ar'],28,True,True)
        rect(s,.75,6.92,11.8,.015,'#E8B84A');tb(s,.75,7.02,8,.25,'hello@athar.example · Riyadh / الرياض · EDITABLE TEMPLATE',9);tb(s,10.2,7.02,2.3,.25,f'AI-PRS-2026-001 · {i+1:02d}/13',9)
        if i==0:
            s.shapes.add_picture(str(ASSETS/'Athar-Int.png'),Inches(.75),Inches(2.2),width=Inches(3.9))
