def build_library():
    DOCS.sort(key=lambda d:d['slug'])
    (ROOT/'manifest.json').write_text(json.dumps(DOCS,ensure_ascii=False,indent=2))
    cards=''.join(f'<article><div class="num">{d["slug"][:2]}</div><h2>{esc(d["en"])}</h2><p lang="ar" dir="rtl">{d["ar"]}</p><small>{d["pages"]} pages · {("85 × 55 mm" if d["mode"]=="card" else "16:9" if d["mode"]=="slides" else "A4")}</small><div class="links"><a href="templates/{d["slug"]}.html">Open & edit / تحرير</a><a href="pdf/{d["slug"]}.pdf">PDF ↓</a></div></article>' for d in DOCS)
    (ROOT/'index.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Athar Corporate Starter Package</title><style>@font-face{font-family:Manrope;src:url('assets/Manrope.ttf');font-weight:200 800}@font-face{font-family:Plex;src:url('assets/IBMPlexSansArabic-Regular.ttf')}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:#F5F8FC;color:#002050;font:15px/1.6 Manrope,sans-serif}[lang=ar]{font-family:Plex,sans-serif}header{padding:24px 6vw;background:white;border-bottom:1px solid #DCE5EF;display:flex;align-items:center;justify-content:space-between;gap:24px}header img{width:200px}header a{color:#0060A8}main{max-width:1280px;margin:auto;padding:50px 5vw}.intro{display:grid;grid-template-columns:1fr 1fr;gap:40px;border-bottom:2px solid #E8B84A;padding-bottom:35px;margin-bottom:35px}h1{font-size:38px;line-height:1.25;margin:12px 0}h2{font-size:18px;margin:8px 0}p{margin:8px 0;color:#526078}.eyebrow{font-size:12px;letter-spacing:2px;color:#0060A8}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0}.actions a{background:#002050;color:white;padding:10px 18px;text-decoration:none;border-radius:4px}.actions a.gold{background:#E8B84A;color:#002050}.catalog{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}article{background:white;padding:24px;border:1px solid #DCE5EF;border-radius:6px;display:flex;flex-direction:column}.num{font-size:12px;color:#0060A8}article p{text-align:left}small{color:#64748B}.links{border-top:1px solid #DCE5EF;margin-top:20px;padding-top:15px;display:flex;justify-content:space-between;gap:10px}.links a{color:#0060A8;font-size:12px}footer{padding:30px 0;font-size:12px;color:#64748B}.swatches{display:flex;gap:8px;margin:18px 0}.swatches span{width:35px;height:7px}input{width:100%;padding:14px;border:1px solid #DCE5EF;font:inherit;margin-bottom:24px}@media(max-width:900px){.catalog{grid-template-columns:repeat(2,1fr)}.intro{grid-template-columns:1fr}h1{font-size:30px}}@media(max-width:550px){.catalog{grid-template-columns:1fr}header{flex-wrap:wrap}}</style></head><body><header><img src="assets/Athar-Horizontal.png" alt="Athar Intelligence official logo"><a href="README.md">Package guide / دليل الحزمة ↗</a></header><main><div class="intro"><div><span class="eyebrow">THE CORPORATE COLLECTION / 2026</span><h1>One identity.<br>Every business essential.</h1><p>15 coordinated Arabic / English template systems. Editable, considered, and ready for your company details.</p><div class="swatches"><span style="background:#002050"></span><span style="background:#0060A8"></span><span style="background:#00B8D9"></span><span style="background:#E8B84A"></span></div></div><div lang="ar" dir="rtl"><span class="eyebrow">المجموعة المؤسسية / ٢٠٢٦</span><h1>هوية واحدة.<br>لكل احتياجات أعمالك.</h1><p>١٥ نظام قوالب منسقاً بالعربية والإنجليزية، قابلة للتحرير وجاهزة لإضافة بيانات شركتك.</p></div></div><div class="actions"><a class="gold" href="Athar-Corporate-Starter.zip">Download package / تنزيل الحزمة ↓</a><a href="presentation/Athar-Corporate-Template.pptx">PowerPoint ↓</a><a href="DESIGN-SYSTEM.md">Design system / نظام التصميم</a><a href="README.md">Instructions / التعليمات</a></div><p>Sample content · بيانات نموذجية — Replace bracketed fields. Financial totals are manual. Legal documents require professional review.</p><input id="search" type="search" aria-label="Search templates / البحث في القوالب" placeholder="Find a template / ابحث عن قالب"><div class="catalog">'''+cards+'''</div><footer>ATHAR INTELLIGENCE / أثر الذكاء · Brand assets preserved · Version 1.0 · 2026-10-02</footer></main><script>document.getElementById('search').addEventListener('input',e=>document.querySelectorAll('article').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(e.target.value.toLowerCase())))</script></body></html>''')

